%[text] # Table-Based Battery block
%[text] This script collects the open-circuit voltage and terminal voltage parameters of table-based battery block in a model file and makes the plots of the parameters.
% Model to collect parameter values.
model_name = "BatteryHV_SystemTable_refsub";
% Block path to the target battery block.
block_path = "/Battery/Battery (Table-Based)";
%[text] Collect parameter values from the battery block in the model.
full_block_path = model_name + block_path;
BatteryHV_TestModelSetup
load_system(model_name)

% State of charge ... independent variable 1
SOC_normalized = eval(get_param(full_block_path, "SOC_vec"))';
SOC_pct = SOC_normalized * 100;

% Battery temperature ... independent variable 2
T_vec = eval(get_param(full_block_path, "T_vec"));
T_vec_unit = get_param(full_block_path, "T_vec_unit");
TemperatureStr = "" + eval(get_param(full_block_path, "T_vec")) + " " + T_vec_unit;
disp(TemperatureStr) %[output:38c5dee1]

% Open-circuit voltage, V0(SOC,T)
V0_mat = eval(get_param(full_block_path, "V0_mat"));
head(V0_mat) %[output:42fc3f20]
V0_mat_unit = get_param(full_block_path, "V0_mat_unit");
disp(V0_mat_unit) %[output:61f31e4d]

% Terminal resistance, R0(SOC,T)
R0_mat = eval(get_param(full_block_path, "R0_mat"));
head(R0_mat) %[output:996f7c16]
R0_mat_unit = get_param(full_block_path, "R0_mat_unit");
disp(R0_mat_unit) %[output:362fc5b1]
%[text] ## Open-ciruit voltage
fig = figure; %[output:6ed1392f]
fig.Position(3:4) = [600 400]; %[output:6ed1392f]
hold on %[output:6ed1392f]
grid on %[output:6ed1392f]
for idx = 1 : numel(T_vec)
  plot(SOC_pct, V0_mat(:,idx), LineWidth=2) %[output:6ed1392f]
end
set(gca, xdir = "reverse") %[output:6ed1392f]
legend(TemperatureStr, Location="southwest") %[output:6ed1392f]
xlabel("State of charge (%)") %[output:6ed1392f]
ylabel("(" + V0_mat_unit + ")") %[output:6ed1392f]
title("Open-circuit voltage, V0(SOC,T)") %[output:6ed1392f]
%[text] ## Terminal resistance
fig = figure; %[output:55bdbb03]
fig.Position(3:4) = [600 400]; %[output:55bdbb03]
hold on %[output:55bdbb03]
grid on %[output:55bdbb03]
for idx = 1 : numel(T_vec)
  plot(SOC_pct, R0_mat(:,idx), LineWidth=2) %[output:55bdbb03]
end
set(gca, xdir = "reverse") %[output:55bdbb03]
legend(TemperatureStr, Location="best") %[output:55bdbb03]
xlabel("State of charge (%)") %[output:55bdbb03]
ylabel("(" + R0_mat_unit + ")") %[output:55bdbb03]
title("Terminal resistance, R0(SOC,T)") %[output:55bdbb03]
